<script setup lang="ts">
import type { LibraryDocument } from '../../api/library'
import AppIcon from '../AppIcon.vue'
withDefaults(defineProps<{ documents: LibraryDocument[]; view: 'list' | 'card'; loading?: boolean; error?: string; selected?: number[] }>(), { loading: false, error: '', selected: () => [] })
defineEmits<{ retry: []; favorite: [document: LibraryDocument]; action: [kind: 'rename'|'move'|'delete', document: LibraryDocument]; select: [id: number] }>()
const size = (bytes: number) => bytes < 1048576 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / 1048576).toFixed(1)} MB`
</script>
<template><div v-if="loading" class="document-skeleton" aria-label="正在加载资料"><span v-for="n in 5" :key="n" /></div><section v-else-if="error" class="feedback-state error-state"><h2>资料暂时无法加载</h2><p>{{ error }}</p><button class="button secondary" aria-label="重试加载资料" @click="$emit('retry')">重试</button></section><section v-else-if="!documents.length" class="feedback-state"><AppIcon name="library"/><h2>资料库还是空的</h2><p>上传第一份 PDF、Markdown、文本或代码资料开始整理。</p></section><div v-else :class="['document-list', `view-${view}`]"><article v-for="document in documents" :key="document.id" data-document-row class="document-row"><input type="checkbox" :checked="selected.includes(document.id)" :aria-label="`选择 ${document.name}`" @change="$emit('select', document.id)"/><a class="document-open" :href="`/reader/${document.id}`" :aria-label="`打开 ${document.name}`"><span class="file-type">{{ document.documentType.slice(0,3) }}</span><span><strong>{{ document.name }}</strong><small>{{ size(document.sizeBytes) }} · {{ document.pageCount ? `${document.pageCount} 页 · ` : '' }}{{ new Date(document.updatedAt).toLocaleDateString() }}</small></span></a><div class="document-tags"><span v-for="tag in document.tags" :key="tag.id">{{ tag.name }}</span></div><span :class="['parse-state', document.status.toLowerCase()]">{{ document.status === 'READY' ? '可阅读' : document.status === 'PROCESSING' ? '解析中' : '失败' }}</span><div class="row-actions"><button :aria-label="`${document.favorite ? '取消收藏' : '收藏'} ${document.name}`" :title="document.favorite ? '取消收藏' : '收藏'" @click="$emit('favorite', document)"><AppIcon name="star"/></button><details><summary :aria-label="`更多操作 ${document.name}`"><AppIcon name="more"/></summary><div><button @click="$emit('action','rename',document)">重命名</button><button @click="$emit('action','move',document)">移动</button><button class="danger-text" @click="$emit('action','delete',document)">删除</button></div></details></div></article></div></template>
